while not done:
    draft = []
    ctx = prefix
    for i in range(gamma):
        token = sample(q(. | ctx))
        draft.append(token)
        ctx += token

    p_scores = target_model.score(prefix + draft)

    accepted = []
    for i, token in enumerate(draft):
        if random() <= min(1, p_scores[i][token] / q_score(i, token)):
            accepted.append(token)
        else:
            correction = sample(residual(p_scores[i], q_score(i)))
            prefix += accepted + [correction]
            break
    else:
        bonus = sample(p_scores_next)
        prefix += accepted + [bonus]
